#!/usr/bin/env python3
"""A byte viewer, implemented from its observable command-line behavior.

Rendering, number parsing and command-line handling are self-contained and use
only Python's standard library. Eight bytes form each data/character panel.
"""
import os
import sys
import re
import stat
import errno
import unicodedata

from interface import HELP_SHORT, HELP_LONG, COMPLETIONS

ESC = '\x1b['
RESET = ESC + '39m'
MAX_SIGNED = (1 << 63) - 1
MAX_UNSIGNED = (1 << 64) - 1


class Failure(Exception):
    def __init__(self, message, status=1):
        self.message = message
        self.status = status


def debug_string(s):
    """The quoted form used in diagnostics (including non-ASCII filenames)."""
    pieces = ['"']
    special = {'\0': '\\0', '\t': '\\t', '\r': '\\r', '\n': '\\n',
               '\\': '\\\\', '"': '\\"'}
    for c in s:
        if c in special:
            pieces.append(special[c])
        elif unicodedata.category(c)[0] == 'C' or unicodedata.category(c) in ('Zl', 'Zp'):
            pieces.append('\\u{' + format(ord(c), 'x') + '}')
        else:
            pieces.append(c)
    return ''.join(pieces) + '"'


def app_error(message, causes=()):
    text = 'Error: ' + message + '\n'
    if causes:
        text += '\nCaused by:\n'
        if len(causes) == 1:
            text += '    ' + causes[0] + '\n'
        else:
            text += ''.join('    %d: %s\n' % (i, cause) for i, cause in enumerate(causes))
    raise Failure(text)


# (name, argument label, short options, aliases, valid values)
SPECS = [
    ('length', 'N', 'ncl', ['bytes'], None),
    ('skip', 'N', 's', [], None),
    ('block-size', 'SIZE', '', [], None),
    ('no-squeezing', None, 'v', [], None),
    ('color', 'WHEN', '', [], ['always', 'auto', 'never', 'force']),
    ('border', 'STYLE', '', [], ['unicode', 'ascii', 'none']),
    ('plain', None, 'p', [], None),
    ('no-characters', None, '', [], None),
    ('characters', None, 'C', [], None),
    ('character-table', 'FORMAT', '', [], ['default', 'ascii', 'codepage-1047', 'codepage-437', 'braille']),
    ('color-scheme', 'FORMAT', '', [], ['default', 'gradient']),
    ('no-position', None, 'P', [], None),
    ('display-offset', 'N', 'o', [], None),
    ('panels', 'N', '', [], None),
    ('group-size', 'N', 'g', ['groupsize'], ['1', '2', '4', '8']),
    ('endianness', 'FORMAT', '', [], ['little', 'big']),
    ('e', None, 'e', [], None),
    ('base', 'B', 'b', [], None),
    ('terminal-width', 'N', '', [], None),
    ('print-color-table', None, '', [], None),
    ('include', None, 'i', [], None),
    ('completion', 'SHELL', '', [], ['bash', 'elvish', 'fish', 'powershell', 'zsh']),
    ('help', None, 'h', [], None),
    ('version', None, 'V', [], None),
]
SPEC = {a[0]: a for a in SPECS}
LONG = {alias: a[0] for a in SPECS if a[0] != 'e' for alias in [a[0], *a[3]]}
SHORT = {c: a[0] for a in SPECS for c in a[2]}


def arg_label(name):
    if name == 'FILE':
        return '<FILE>'
    if name == 'e':
        return '-e'
    label = '--' + name
    if SPEC[name][1]:
        label += ' <' + SPEC[name][1] + '>'
    return label


def similarity(a, b):
    """Jaro-Winkler score, for command-line typo suggestions."""
    if a == b:
        return 1.0
    d = max(len(a), len(b)) // 2 - 1
    d = max(0, d)
    used_a, used_b = [False]*len(a), [False]*len(b)
    m = 0
    for i, c in enumerate(a):
        for j in range(max(0, i-d), min(i+d+1, len(b))):
            if not used_b[j] and c == b[j]:
                used_a[i], used_b[j] = True, True
                m += 1
                break
    if not m:
        return 0.0
    aa = [c for c, u in zip(a, used_a) if u]
    bb = [c for c, u in zip(b, used_b) if u]
    t = sum(x != y for x, y in zip(aa, bb)) / 2
    s = (m/len(a) + m/len(b) + (m-t)/m) / 3
    if s > .7:
        prefix = 0
        for x, y in zip(a[:4], b[:4]):
            if x != y:
                break
            prefix += 1
        s += prefix * .1 * (1-s)
    return s


def suggestion(word, values):
    scores = [(similarity(word, value), i, value) for i, value in enumerate(values)]
    scores = [a for a in scores if a[0] > .8]
    if not scores:
        return None
    return max(scores)[2]


def usage_all(program):
    opts = ['FILE'] + [arg_label(a[0]) for a in SPECS[:-2]]
    return program + ' <' + '|'.join(opts) + '>'


def cli_error(message, usage=None, extra=''):
    result = 'error: ' + message + '\n'
    if extra:
        result += extra
    if usage is not None:
        result += '\nUsage: ' + usage + '\n'
    result += "\nFor more information, try '--help'.\n"
    raise Failure(result, 2)


def missing_value(name):
    values = SPEC[name][4]
    extra = ('  [possible values: ' + ', '.join(values) + ']\n') if values else ''
    cli_error("a value is required for '%s' but none was supplied" % arg_label(name), extra=extra)


def invalid_value(name, value, reason=None):
    label = arg_label(name)
    if reason is not None:
        cli_error("invalid value '%s' for '%s': %s" % (value, label, reason))
    values = SPEC[name][4]
    extra = '  [possible values: ' + ', '.join(values) + ']\n'
    proposed = suggestion(value, values)
    if proposed:
        extra += "\n  tip: a similar value exists: '%s'\n" % proposed
    cli_error("invalid value '%s' for '%s'" % (value, label), extra=extra)


def parse_unsigned(value, limit=MAX_UNSIGNED, nonzero=False):
    if not value:
        return None, 'cannot parse integer from empty string'
    if not re.fullmatch(r'\+?[0-9]+', value):
        return None, 'invalid digit found in string'
    try:
        number = int(value)
    except ValueError:
        return None, 'number too large to fit in target type'
    if number > limit:
        return None, 'number too large to fit in target type'
    if nonzero and number == 0:
        return None, 'number would be zero for non-zero type'
    return number, None


class Options:
    def __init__(self, program):
        self.program = program
        self.values = {}
        self.order = []
        self.file = None
        self.file_seen = False

    def __contains__(self, key):
        return key in self.values

    def get(self, key, default=None):
        return self.values.get(key, default)

    def current_usage(self, exclude=()):
        names = [name for name in self.order if name not in exclude and name != 'FILE']
        body = ' '.join(arg_label(name) for name in names)
        return self.program + (' ' + body if body else '') + ' [FILE]'

    def unknown(self, value):
        proposed = None
        if value.startswith('--'):
            proposed = suggestion(value[2:], list(LONG))
        if proposed:
            extra = "\n  tip: a similar argument exists: '--%s'\n" % proposed
            usage = usage_all(self.program)
        else:
            extra = ("\n  tip: to pass '%s' as a value, use '-- %s'\n" % (value, value)) if value.startswith('-') else ''
            usage = self.program + ' [OPTIONS] [FILE]'
        cli_error("unexpected argument '%s' found" % value, usage, extra)

    def add(self, name, value, long_form=False):
        if name == 'help':
            text = HELP_LONG if long_form else HELP_SHORT
            sys.stdout.write(text.replace('Usage: executable ', 'Usage: ' + self.program + ' '))
            raise SystemExit(0)
        if name == 'version':
            sys.stdout.write('hexyl 0.16.0\n')
            raise SystemExit(0)
        if name in self.values:
            cli_error("the argument '%s' cannot be used multiple times" % arg_label(name), self.program + ' [OPTIONS] [FILE]')
        if SPEC[name][4] and value not in SPEC[name][4]:
            if value == '':
                missing_value(name)
            invalid_value(name, value)
        if name == 'terminal-width':
            number, err = parse_unsigned(value, 65535, True)
            if err:
                invalid_value(name, value, err)
            value = number
        opposites = {'no-characters': 'characters', 'characters': 'no-characters',
                     'endianness': 'e', 'e': 'endianness'}
        other = opposites.get(name)
        if other in self.values:
            del self.values[other]
            self.order.remove(other)
        self.values[name] = value
        self.order.append(name)

    def conflicts(self):
        pairs = [('include', 'endianness'), ('include', 'e'), ('terminal-width', 'panels')]
        for a in self.order:
            conflicts = []
            for x, y in pairs:
                if a == x and y in self.values:
                    conflicts.append(y)
                elif a == y and x in self.values:
                    conflicts.append(x)
            if conflicts:
                b = conflicts[0]
                cli_error("the argument '%s' cannot be used with '%s'" % (arg_label(a), arg_label(b)), self.current_usage(conflicts))


def parse_cli(argv):
    program = os.path.basename(sys.argv[0]) or 'executable'
    opts = Options(program)
    i = 0
    positional = False
    while i < len(argv):
        token = argv[i]
        i += 1
        if not positional and token == '--':
            positional = True
            continue
        if not positional and token.startswith('--'):
            key, equal, value = token[2:].partition('=')
            name = LONG.get(key)
            if name is None:
                opts.unknown('--' + key)
            takes_value = SPEC[name][1] is not None
            if not takes_value:
                if equal:
                    if name not in opts.order:
                        opts.order.append(name)
                    cli_error("unexpected value '%s' for '%s' found; no more were expected" % (value, arg_label(name)), opts.current_usage())
                opts.add(name, True, True)
            else:
                if not equal:
                    if i == len(argv):
                        missing_value(name)
                    value = argv[i]
                    if value.startswith('-') and value != '-':
                        known = value == '--' or (value.startswith('--') and value[2:].split('=')[0] in LONG) or (not value.startswith('--') and value[1:2] in SHORT)
                        if known:
                            missing_value(name)
                        opts.unknown(value.split('=')[0] if value.startswith('--') else value[:2])
                    i += 1
                opts.add(name, value, True)
        elif not positional and token.startswith('-') and token != '-':
            j = 1
            while j < len(token):
                letter = token[j]
                j += 1
                name = SHORT.get(letter)
                if name is None:
                    opts.unknown('-' + letter)
                if SPEC[name][1] is None:
                    opts.add(name, True)
                    continue
                if j < len(token):
                    value = token[j:]
                    if value.startswith('='):
                        value = value[1:]
                    j = len(token)
                else:
                    if i == len(argv):
                        missing_value(name)
                    value = argv[i]
                    if value.startswith('-') and value != '-':
                        known = value == '--' or (value.startswith('--') and value[2:].split('=')[0] in LONG) or (not value.startswith('--') and value[1:2] in SHORT)
                        if known:
                            missing_value(name)
                        opts.unknown(value.split('=')[0] if value.startswith('--') else value[:2])
                    i += 1
                opts.add(name, value)
        else:
            if opts.file_seen:
                opts.unknown(token)
            opts.file = token
            opts.file_seen = True
            opts.order.append('FILE')
    opts.conflicts()
    return opts


class CountError(Exception):
    def __init__(self, *chain):
        self.chain = chain


def positive_count(text, block_size):
    if text.startswith('0x'):
        digits = text[2:]
        if digits.startswith(('+', '-')):
            raise CountError('found %r sign after hex prefix ("0x"); signs should go before it' % digits[0])
        if not digits:
            raise CountError('failed to parse integer part', 'cannot parse integer from empty string')
        if not re.fullmatch(r'[a-fA-F0-9]+', digits):
            raise CountError('failed to parse integer part', 'invalid digit found in string')
        try:
            number = int(digits, 16)
        except ValueError:
            number = MAX_SIGNED + 1
        multiplier = 1
    else:
        m = re.match(r'^([0-9]+)([\s\S]*)$', text)
        if not m:
            raise CountError(debug_string(text) + ' is not of the expected form <pos-integer>[<unit>]')
        digits, unit = m.groups()
        units = {'': 1, 'kb': 1000, 'mb': 1000**2, 'gb': 1000**3, 'tb': 1000**4,
                 'kib': 1024, 'mib': 1024**2, 'gib': 1024**3, 'tib': 1024**4,
                 'block': block_size, 'blocks': block_size}
        if unit.lower() not in units:
            raise CountError('invalid unit ' + debug_string(unit))
        multiplier = units[unit.lower()]
        if multiplier is None:
            raise CountError("can not use 'block(s)' as a unit to specify block size")
        try:
            number = int(digits)
        except ValueError:
            number = MAX_SIGNED + 1
    if number > MAX_SIGNED:
        raise CountError('failed to parse integer part', 'number too large to fit in target type')
    number *= multiplier
    if number > MAX_SIGNED:
        raise CountError('count multiplied by the unit overflowed a signed 64-bit integer; are you sure it should be that big?')
    return number


def count_argument(name, value, block_size, signed=False):
    try:
        if not value:
            raise CountError('no character data found, did you forget to write it?')
        negative = value.startswith('-')
        unsigned = value[1:] if value.startswith(('+', '-')) else value
        if not unsigned:
            raise CountError('no digits found after sign, did you forget to write them?')
        number = positive_count(unsigned, block_size)
        if negative and not signed:
            raise CountError('negative offset specified, but only positive offsets (counts) are accepted in this context')
        return number, negative
    except CountError as e:
        app_error('failed to parse `--%s` arg %s as byte count' % (name, debug_string(value)), e.chain)


def parse_base(text):
    bases = {'b': 2, 'bin': 2, 'binary': 2, 'o': 8, 'oct': 8, 'octal': 8,
             'd': 10, 'dec': 10, 'decimal': 10, 'x': 16, 'hex': 16, 'hexadecimal': 16}
    if text in bases:
        return bases[text]
    value, err = parse_unsigned(text, 255)
    if err:
        app_error('The base provided is not valid. Valid bases are "b", "o", "d", and "x".')
    if value not in (2, 8, 10, 16):
        app_error('The number provided is not a valid base. Valid bases are 2, 8, 10, and 16.')
    return value


def env_color(key, default):
    value = os.environ.get('HEXYL_COLOR_' + key, '')
    names = ['black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white']
    colors = {name: ESC + str(30+i) + 'm' for i, name in enumerate(names)}
    colors.update({'bright '+name: ESC + str(90+i) + 'm' for i, name in enumerate(names)})
    colors['purple'] = colors['magenta']
    colors['bright purple'] = colors['bright magenta']
    if value in colors:
        return colors[value]
    if re.fullmatch(r'#[a-fA-F0-9]{6}', value):
        rgb = [int(value[i:i+2], 16) for i in (1, 3, 5)]
        return ESC + '38;2;%d;%d;%dm' % tuple(rgb)
    return ESC + str(default) + 'm'


def default_palette():
    null = env_color('NULL', 90)
    printable = env_color('ASCII_PRINTABLE', 36)
    whitespace = env_color('ASCII_WHITESPACE', 32)
    other = env_color('ASCII_OTHER', 32)
    nonascii = env_color('NONASCII', 33)
    palette = []
    for b in range(256):
        if b == 0:
            palette.append(null)
        elif b in (9, 10, 12, 13, 32):
            palette.append(whitespace)
        elif 33 <= b <= 126:
            palette.append(printable)
        elif b < 128:
            palette.append(other)
        else:
            palette.append(nonascii)
    return palette


def print_color_table():
    p = default_palette()
    entries = [(0, '⋄ NULL bytes (0x00)'), (97, 'a ASCII printable characters (0x20 - 0x7E)'),
               (10, '_ ASCII whitespace (0x09 - 0x0D, 0x20)'),
               (1, '• ASCII control characters (except NULL and whitespace)'),
               (128, '× Non-ASCII bytes (0x80 - 0xFF)')]
    sys.stdout.write('hexyl color reference:\n\n' + ''.join(p[b] + line + '\n' + RESET for b, line in entries))


# The optional encodings are display alphabets, not conversions of the input.
CP1047 = (
    '................................................................'
    ' .........$.<(+|&.........!$*);.-/.........,%_>?'
    "..........:#@'=."
    '.abcdefghi.{.(+..jklmnopqr.}.)...~stuvwxyz......'
    '..........[]...-{ABCDEFGHI......}JKLMNOPQR......'
    '..STUVWXYZ......0123456789......'
)
CP437 = (
    '⋄☺☻♥♦♣♠•◘○◙♂♀♪♫☼►◄↕‼¶§▬↨↑↓→←∟↔▲▼'
    ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~⌂'
    'ÇüéâäàåçêëèïîìÄÅÉæÆôöòûùÿÖÜ¢£¥₧ƒáíóúñÑªº¿⌐¬½¼¡«»'
    '░▒▓│┤╡╢╖╕╣║╗╝╜╛┐└┴┬├─┼╞╟╚╔╩╦╠═╬╧'
    '╨╤╥╙╘╒╓╫╪┘┌█▄▌▐▀αßΓπΣσµτΦΘΩδ∞φε∩'
    '≡±≥≤⌠⌡÷≈°∙·√ⁿ²■ﬀ'
)


def character_map(name):
    if name == 'codepage-1047':
        return CP1047
    if name == 'codepage-437':
        return CP437
    result = []
    for b in range(256):
        if 32 <= b <= 126:
            c = chr(b)
        elif name == 'ascii':
            c = '.'
        elif name == 'braille':
            if b == 0:
                c = '⋄'
            elif b in (9, 10, 13):
                c = {9: '→', 10: '↵', 13: '←'}[b]
            else:
                dots = [0, 3, 1, 4, 2, 5, 6, 7]
                c = chr(0x2800 + sum(((b >> bit) & 1) << dots[bit] for bit in range(8)))
        elif b == 0:
            c = '⋄'
        elif b in (9, 10, 12, 13):
            c = '_'
        elif b < 128:
            c = '•'
        else:
            c = '×'
        result.append(c)
    return result


# A gradient color is specified for each of the 256 byte values. The small
# lookup tables below keep the integer rounding of the display palette stable.
GRADIENT_RGB = ()  # filled in below


def gradient_palette():
    return [ESC + '38;2;%03d;%03d;%03dm' % rgb for rgb in GRADIENT_RGB]


def terminal_width():
    for fd in (1, 2, 0):
        try:
            cols = os.get_terminal_size(fd).columns
            if cols:
                return cols
        except OSError:
            pass
    return 80


def format_offset(position):
    position &= MAX_UNSIGNED
    width = max(8, ((position.bit_length() + 7) // 8)*2)
    return format(position, '0%dx' % width)


class Viewer:
    def __init__(self, options, base):
        self.group = int(options.get('group-size', '1'))
        self.little = 'e' in options or options.get('endianness') == 'little'
        plain = 'plain' in options
        self.characters = not plain and 'no-characters' not in options
        self.position = not plain and 'no-position' not in options
        self.border = options.get('border', 'none' if plain else 'unicode')
        when = options.get('color', 'never' if plain else 'always')
        self.color = when == 'force' or ('NO_COLOR' not in os.environ and (when == 'always' or when == 'auto' and os.isatty(1)))
        self.reset = RESET if self.color else ''
        self.offset_color = env_color('OFFSET', 90) if self.color else ''
        if self.color:
            self.colors = gradient_palette() if options.get('color-scheme') == 'gradient' else default_palette()
        else:
            self.colors = [''] * 256
        self.chars = character_map(options.get('character-table', 'default'))
        self.base = base
        self.digits = {2: 8, 8: 3, 10: 3, 16: 2}[base]
        self.numbers = [format(i, {2:'08b', 8:'03o', 10:'03d', 16:'02x'}[base]) for i in range(256)]
        self.panel_width = self.digits * 8 + 8 // self.group + 1
        panels = options.get('panels')
        if panels is not None and panels != 'auto':
            self.panels, err = parse_unsigned(panels, MAX_UNSIGNED, True)
            if err:
                app_error('failed to parse `--panels` arg %s as unsigned nonzero integer' % debug_string(panels), [err])
        else:
            width = options.get('terminal-width', terminal_width())
            fixed = 1 + (9 if self.position else 0)
            per_panel = self.panel_width + 1 + (8 if self.characters else 0)
            self.panels = max(1, (width - fixed) // per_panel)
            if panels is None and 'terminal-width' not in options:
                self.panels = min(2, self.panels)
        self.squeeze = 'no-squeezing' not in options
        if self.border == 'unicode':
            self.wall, self.divider = '│', '┊'
        elif self.border == 'ascii':
            self.wall = self.divider = '|'
        else:
            self.wall = self.divider = ' '

    def rule(self, top=True, empty=False):
        if self.border == 'none':
            return ''
        n = (16 + 8 // self.group + 1) if empty else self.panel_width
        segments = ([8] if self.position else []) + [n] * self.panels + ([8] * self.panels if self.characters else [])
        if self.border == 'ascii':
            left, join, right, fill = '+', '+', '+', '-'
        else:
            left, join, right, fill = ('┌', '┬', '┐', '─') if top else ('└', '┴', '┘', '─')
        return left + join.join(fill * width for width in segments) + right + '\n'

    def empty(self):
        width = 16 + 8 // self.group + 1
        parts = ([' ' * 8] if self.position else []) + [' No content'.ljust(width), ' ' * width]
        if self.characters:
            parts += [' ' * 8, ' ' * 8]
        return self.rule(True, True) + '│' + '│'.join(parts) + '│\n' + self.rule(False, True)

    def byte_panel(self, data):
        text = []
        current_color = None
        for group_start in range(0, 8, self.group):
            text.append(' ')
            group = data[group_start:group_start + self.group]
            if self.little:
                group = group[::-1]
            for b in group:
                color = self.colors[b]
                if color != current_color:
                    text.append(color)
                    current_color = color
                text.append(self.numbers[b])
            text.append(' ' * ((self.group - len(group)) * self.digits))
        text += [self.reset, ' ']
        return ''.join(text)

    def char_panel(self, data):
        text = []
        current_color = None
        for b in data:
            color = self.colors[b]
            if color != current_color:
                text.append(color)
                current_color = color
            text.append(self.chars[b])
        text += [' ' * (8-len(data)), self.reset]
        return ''.join(text)

    def row(self, data, position):
        out = [self.wall, self.offset_color]
        if self.position:
            out += [format_offset(position), self.reset, self.wall]
        for p in range(self.panels):
            out.append(self.byte_panel(data[p*8:p*8+8]))
            out.append(self.divider if p+1 < self.panels else self.wall)
        if self.characters:
            for p in range(self.panels):
                out.append(self.char_panel(data[p*8:p*8+8]))
                out.append(self.divider if p+1 < self.panels else self.wall)
        out.append('\n')
        return ''.join(out)

    def marker(self, position=None):
        out = [self.wall, self.offset_color]
        if self.position:
            if position is None:
                out += ['*', self.reset, ' '*7, self.wall]
            else:
                out += [format_offset(position), self.reset, self.wall]
        for p in range(self.panels):
            if not self.position and p == 0:
                out += [self.offset_color, '*', self.reset, ' '*(self.panel_width-2), self.reset, ' ']
            else:
                out += [' ' * (self.panel_width-1), self.reset, ' ']
            out.append(self.divider if p+1 < self.panels else self.wall)
        if self.characters:
            for p in range(self.panels):
                out += [' ' * 8, self.reset, self.divider if p+1 < self.panels else self.wall]
        out.append('\n')
        return ''.join(out)

    def render(self, reader, length, offset):
        size = self.panels * 8
        first = True
        previous = None
        squeezed = False
        left = length
        while left is None or left > 0:
            requested = size if left is None else min(size, left)
            data = reader.read(requested)
            if not data:
                break
            if first:
                yield self.rule()
                first = False
            if self.squeeze and data == previous:
                if not squeezed:
                    yield self.marker()
                squeezed = True
            else:
                yield self.row(data, offset)
                squeezed = False
            previous = data
            offset += len(data)
            if left is not None:
                left -= len(data)
        if first:
            yield self.empty()
        else:
            if squeezed:
                yield self.marker(offset)
            yield self.rule(False)


SEEK_ERROR = ('Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).')


def open_input(path):
    if path is None:
        return sys.stdin.buffer
    try:
        f = open(path, 'rb')
    except IsADirectoryError:
        app_error("'%s' is a directory." % path)
    except OSError as e:
        app_error('%s (os error %d)' % (e.strerror, e.errno))
    return f


def apply_skip(reader, count, from_end):
    if from_end:
        try:
            return reader.seek(-count, os.SEEK_END)
        except (OSError, ValueError, OverflowError):
            app_error(SEEK_ERROR)
    try:
        return reader.seek(count, os.SEEK_CUR)
    except (OSError, ValueError, OverflowError):
        remaining = count
        while remaining:
            chunk = reader.read(min(remaining, 65536))
            if not chunk:
                break
            remaining -= len(chunk)
        return count - remaining


def include_output(reader, filename, length):
    name = None
    if filename is not None:
        basename = os.path.basename(os.path.normpath(filename))
        name = ''.join(c if c.isalnum() else '_' for c in basename)
        yield 'unsigned char ' + name + '[] = {\n'
    left = length
    previous = None
    total = 0
    while left is None or left > 0:
        data = reader.read(12 if left is None else min(12, left))
        if not data:
            break
        if previous is not None:
            yield previous + ',\n'
        previous = '  ' + ', '.join('0x%02x' % b for b in data)
        total += len(data)
        if left is not None:
            left -= len(data)
    yield (previous or '') + '\n'
    if name is not None:
        yield '};\nunsigned int %s_len = %d;\n' % (name, total)


def main():
    options = parse_cli(sys.argv[1:])
    if 'print-color-table' in options:
        print_color_table()
        return
    if 'completion' in options:
        sys.stdout.write(COMPLETIONS[options.get('completion')])
        return
    reader = open_input(options.file)
    try:
        block_size = positive_count(options.get('block-size', '512'), None)
    except CountError as e:
        app_error(e.chain[0], e.chain[1:])
    if not block_size:
        app_error('block size argument must be positive')
    offset = 0
    if 'skip' in options:
        count, negative = count_argument('skip', options.get('skip'), block_size, True)
        offset = apply_skip(reader, count, negative)
    length = None
    if 'length' in options:
        length = count_argument('length', options.get('length'), block_size)[0]
    displayed = count_argument('display-offset', options.get('display-offset', '0'), block_size)[0]
    base = parse_base(options.get('base', 'hexadecimal'))
    viewer = Viewer(options, base)
    if 'include' in options:
        output = include_output(reader, options.file, length)
    else:
        output = viewer.render(reader, length, offset+displayed)
    for text in output:
        sys.stdout.write(text)


def entrypoint():
    try:
        main()
        sys.stdout.flush()
    except Failure as e:
        sys.stderr.write(e.message)
        raise SystemExit(e.status)
    except BrokenPipeError:
        # Early-closing consumers (for example head) are not an application error.
        try:
            sys.stdout.close()
        except OSError:
            pass
        os._exit(0)
    except OSError as e:
        sys.stderr.write('Error: %s (os error %d)\n' % (e.strerror, e.errno))
        raise SystemExit(1)


if __name__ == '__main__':
    entrypoint()
