def character_map(name):
    if name == 'codepage-1047':
        return CP1047
    if name == 'codepage-437':
        return CP437
    result = []
    for b in range(256):
        if 32 <= b <= 126:
            c = chr(b)
        elif name == 'ascii':
            c = '.'
        elif name == 'braille':
            if b == 0:
                c = '⋄'
            elif b in (9, 10, 13):
                c = {9: '→', 10: '↵', 13: '←'}[b]
            else:
                dots = [0, 3, 1, 4, 2, 5, 6, 7]
                c = chr(0x2800 + sum(((b >> bit) & 1) << dots[bit] for bit in range(8)))
        elif b == 0:
            c = '⋄'
        elif b in (9, 10, 12, 13):
            c = '_'
        elif b < 128:
            c = '•'
        else:
            c = '×'
        result.append(c)
    return result


# A gradient color is specified for each of the 256 byte values. The small
# lookup tables below keep the integer rounding of the display palette stable.
GRADIENT_RGB = ()  # filled in below


def gradient_palette():
