def terminal_width():
    for fd in (1, 2, 0):
        try:
            cols = os.get_terminal_size(fd).columns
            if cols:
                return cols
        except OSError:
            pass
    return 80


def format_offset(position):
    position &= MAX_UNSIGNED
    width = max(8, ((position.bit_length() + 7) // 8)*2)
    return format(position, '0%dx' % width)


class Viewer:
    def __init__(self, options, base):
        self.group = int(options.get('group-size', '1'))
        self.little = 'e' in options or options.get('endianness') == 'little'
        plain = 'plain' in options
        self.characters = not plain and 'no-characters' not in options
        self.position = not plain and 'no-position' not in options
        self.border = options.get('border', 'none' if plain else 'unicode')
        when = options.get('color', 'never' if plain else 'always')
        self.color = when == 'force' or ('NO_COLOR' not in os.environ and (when == 'always' or when == 'auto' and os.isatty(1)))
        self.reset = RESET if self.color else ''
        self.offset_color = env_color('OFFSET', 90) if self.color else ''
        if self.color:
            self.colors = gradient_palette() if options.get('color-scheme') == 'gradient' else default_palette()
        else:
            self.colors = [''] * 256
        self.chars = character_map(options.get('character-table', 'default'))
        self.base = base
        self.digits = {2: 8, 8: 3, 10: 3, 16: 2}[base]
        self.numbers = [format(i, {2:'08b', 8:'03o', 10:'03d', 16:'02x'}[base]) for i in range(256)]
        self.panel_width = self.digits * 8 + 8 // self.group + 1
        panels = options.get('panels')
        if panels is not None and panels != 'auto':
            self.panels, err = parse_unsigned(panels, MAX_UNSIGNED, True)
            if err:
                app_error('failed to parse `--panels` arg %s as unsigned nonzero integer' % debug_string(panels), [err])
        else:
            width = options.get('terminal-width', terminal_width())
            fixed = 1 + (9 if self.position else 0)
            per_panel = self.panel_width + 1 + (8 if self.characters else 0)
            self.panels = max(1, (width - fixed) // per_panel)
            if panels is None and 'terminal-width' not in options:
                self.panels = min(2, self.panels)
        self.squeeze = 'no-squeezing' not in options
        if self.border == 'unicode':
            self.wall, self.divider = '│', '┊'
        elif self.border == 'ascii':
            self.wall = self.divider = '|'
        else:
            self.wall = self.divider = ' '

    def rule(self, top=True, empty=False):
        if self.border == 'none':
            return ''
        n = (16 + 8 // self.group + 1) if empty else self.panel_width
        segments = ([8] if self.position else []) + [n] * self.panels + ([8] * self.panels if self.characters else [])
        if self.border == 'ascii':
            left, join, right, fill = '+', '+', '+', '-'
        else:
            left, join, right, fill = ('┌', '┬', '┐', '─') if top else ('└', '┴', '┘', '─')
        return left + join.join(fill * width for width in segments) + right + '\n'

    def empty(self):
        width = 16 + 8 // self.group + 1
        parts = ([' ' * 8] if self.position else []) + [' No content'.ljust(width), ' ' * width]
        if self.characters:
            parts += [' ' * 8, ' ' * 8]
        return self.rule(True, True) + '│' + '│'.join(parts) + '│\n' + self.rule(False, True)

    def byte_panel(self, data):
        text = []
        current_color = None
        for group_start in range(0, 8, self.group):
            text.append(' ')
            group = data[group_start:group_start + self.group]
            if self.little:
                group = group[::-1]
            for b in group:
                color = self.colors[b]
                if color != current_color:
                    text.append(color)
                    current_color = color
                text.append(self.numbers[b])
            text.append(' ' * ((self.group - len(group)) * self.digits))
        text += [self.reset, ' ']
        return ''.join(text)

    def char_panel(self, data):
        text = []
        current_color = None
        for b in data:
            color = self.colors[b]
            if color != current_color:
                text.append(color)
                current_color = color
            text.append(self.chars[b])
        text += [' ' * (8-len(data)), self.reset]
        return ''.join(text)

    def row(self, data, position):
        out = [self.wall, self.offset_color]
        if self.position:
            out += [format_offset(position), self.reset, self.wall]
        for p in range(self.panels):
            out.append(self.byte_panel(data[p*8:p*8+8]))
            out.append(self.divider if p+1 < self.panels else self.wall)
        if self.characters:
            for p in range(self.panels):
                out.append(self.char_panel(data[p*8:p*8+8]))
                out.append(self.divider if p+1 < self.panels else self.wall)
        out.append('\n')
        return ''.join(out)

    def marker(self, position=None):
        out = [self.wall, self.offset_color]
        if self.position:
            if position is None:
                out += ['*', self.reset, ' '*7, self.wall]
            else:
                out += [format_offset(position), self.reset, self.wall]
        for p in range(self.panels):
            if not self.position and p == 0:
                out += [self.offset_color, '*', self.reset, ' '*(self.panel_width-2), self.reset, ' ']
            else:
                out += [' ' * (self.panel_width-1), self.reset, ' ']
            out.append(self.divider if p+1 < self.panels else self.wall)
        if self.characters:
            for p in range(self.panels):
                out += [' ' * 8, self.reset, self.divider if p+1 < self.panels else self.wall]
        out.append('\n')
        return ''.join(out)

    def render(self, reader, length, offset):
        size = self.panels * 8
        first = True
        previous = None
        squeezed = False
        left = length
        while left is None or left > 0:
            requested = size if left is None else min(size, left)
            data = reader.read(requested)
            if not data:
                break
            if first:
                yield self.rule()
                first = False
            if self.squeeze and data == previous:
                if not squeezed:
                    yield self.marker()
                squeezed = True
            else:
                yield self.row(data, offset)
                squeezed = False
            previous = data
            offset += len(data)
            if left is not None:
                left -= len(data)
        if first:
            yield self.empty()
        else:
            if squeezed:
                yield self.marker(offset)
            yield self.rule(False)


SEEK_ERROR = ('Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).')


def open_input(path):
    if path is None:
        return sys.stdin.buffer
    try:
        f = open(path, 'rb')
    except IsADirectoryError:
        app_error("'%s' is a directory." % path)
    except OSError as e:
        app_error('%s (os error %d)' % (e.strerror, e.errno))
    return f


def apply_skip(reader, count, from_end):
    if from_end:
        try:
            return reader.seek(-count, os.SEEK_END)
        except (OSError, ValueError, OverflowError):
            app_error(SEEK_ERROR)
    try:
        return reader.seek(count, os.SEEK_CUR)
    except (OSError, ValueError, OverflowError):
        remaining = count
        while remaining:
            chunk = reader.read(min(remaining, 65536))
            if not chunk:
                break
            remaining -= len(chunk)
        return count - remaining


def include_output(reader, filename, length):
    name = None
    if filename is not None:
        basename = os.path.basename(os.path.normpath(filename))
        name = ''.join(c if c.isalnum() else '_' for c in basename)
        yield 'unsigned char ' + name + '[] = {\n'
    left = length
    previous = None
    total = 0
    while left is None or left > 0:
        data = reader.read(12 if left is None else min(12, left))
        if not data:
            break
        if previous is not None:
            yield previous + ',\n'
        previous = '  ' + ', '.join('0x%02x' % b for b in data)
        total += len(data)
        if left is not None:
            left -= len(data)
    yield (previous or '') + '\n'
    if name is not None:
        yield '};\nunsigned int %s_len = %d;\n' % (name, total)


def main():
    options = parse_cli(sys.argv[1:])
    if 'print-color-table' in options:
        print_color_table()
        return
    if 'completion' in options:
        sys.stdout.write(COMPLETIONS[options.get('completion')])
        return
    reader = open_input(options.file)
    try:
        block_size = positive_count(options.get('block-size', '512'), None)
    except CountError as e:
        app_error(e.chain[0], e.chain[1:])
    if not block_size:
        app_error('block size argument must be positive')
    offset = 0
    if 'skip' in options:
        count, negative = count_argument('skip', options.get('skip'), block_size, True)
        offset = apply_skip(reader, count, negative)
    length = None
    if 'length' in options:
        length = count_argument('length', options.get('length'), block_size)[0]
    displayed = count_argument('display-offset', options.get('display-offset', '0'), block_size)[0]
    base = parse_base(options.get('base', 'hexadecimal'))
    viewer = Viewer(options, base)
    if 'include' in options:
        output = include_output(reader, options.file, length)
    else:
        output = viewer.render(reader, length, offset+displayed)
    for text in output:
        sys.stdout.write(text)


def entrypoint():
    try:
        main()
        sys.stdout.flush()
    except Failure as e:
        sys.stderr.write(e.message)
        raise SystemExit(e.status)
    except BrokenPipeError:
        # Early-closing consumers (for example head) are not an application error.
        try:
            sys.stdout.close()
        except OSError:
            pass
        os._exit(0)
    except OSError as e:
        sys.stderr.write('Error: %s (os error %d)\n' % (e.strerror, e.errno))
        raise SystemExit(1)


if __name__ == '__main__':
    entrypoint()
